<script>
	const img = (prompt, size) =>
		'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=' +
		encodeURIComponent(prompt) + '&image_size=' + size

	const STORAGE_KEY = 'qcc_user_profile_data'

	// 企业用户初始数据
	const enterpriseDefault = {
		role: 'enterprise',
		name: '张明远',
		nickname: '明远',
		gender: '男',
		birthday: '1985-06-18',
		phone: '138****8888',
		email: 'zhangmy@mytech.com',
		avatar: img('Professional Chinese businessman avatar portrait, 40s, wearing suit, friendly smile, studio lighting, square format', 'square_hd'),
		enterprises: [
			{ id: 1, name: '上海明远科技有限公司', role: '法人', status: '正常' },
			{ id: 2, name: '上海启航贸易有限公司', role: '股东', status: '正常' },
			{ id: 3, name: '杭州远景咨询有限公司', role: '法人', status: '变更中' }
		]
	}

	// 内部员工初始数据
	const internalDefault = {
		role: 'internal',
		name: '李晓雯',
		nickname: '晓雯',
		gender: '女',
		birthday: '1996-11-22',
		phone: '186****6666',
		email: 'lixiaowen@qichacha.com',
		avatar: img('Professional Chinese young woman employee avatar portrait, 20s, wearing smart casual, friendly smile, office background, square format', 'square_hd'),
		department: '客户服务部',
		empId: 'QC20240128',
		position: '高级客户经理',
		joinDate: '2024-01-28',
		enterprises: [
			{ id: 1, name: '上海明远科技有限公司', role: '对接经理', status: '跟进中' },
			{ id: 2, name: '上海启航贸易有限公司', role: '对接经理', status: '正常' },
			{ id: 3, name: '杭州远景咨询有限公司', role: '对接经理', status: '正常' },
			{ id: 4, name: '苏州恒源实业有限公司', role: '协助', status: '正常' },
			{ id: 5, name: '南京宏图网络有限公司', role: '协助', status: '待联系' }
		]
	}

	export default {
		data() {
			return {
				userRole: 'enterprise',
				form: {}
			}
		},
		computed: {
			today() {
				const d = new Date()
				const m = String(d.getMonth() + 1).padStart(2, '0')
				const day = String(d.getDate()).padStart(2, '0')
				return `${d.getFullYear()}-${m}-${day}`
			}
		},
		onLoad() {
			this.loadFromStorage()
		},
		methods: {
			// 从storage加载，没有则按当前角色使用默认数据
			loadFromStorage() {
				let savedRole = uni.getStorageSync('qcc_user_role')
				if (!savedRole) savedRole = 'enterprise'
				this.userRole = savedRole

				// 尝试从storage读取该角色的最新数据
				const saved = uni.getStorageSync(STORAGE_KEY + '_' + savedRole)
				let base = savedRole === 'enterprise' ? enterpriseDefault : internalDefault
				if (saved && typeof saved === 'object') {
					base = Object.assign({}, base, saved)
				}
				this.form = {
					role: base.role,
					name: base.name,
					nickname: base.nickname || '',
					gender: base.gender || '',
					birthday: base.birthday || '',
					phone: base.phone || '',
					email: base.email || '',
					avatar: base.avatar,
					department: base.department || '',
					empId: base.empId || '',
					position: base.position || '',
					joinDate: base.joinDate || this.today
				}
			},

			// 选择头像
			onChooseAvatar() {
				uni.chooseImage({
					count: 1,
					sizeType: ['compressed'],
					sourceType: ['album', 'camera'],
					success: (res) => {
						if (res.tempFilePaths && res.tempFilePaths[0]) {
							this.form.avatar = res.tempFilePaths[0]
							uni.showToast({ title: '头像已更新', icon: 'success' })
						}
					},
					fail: () => {
						// 演示环境下chooseImage可能不可用，提示
						uni.showToast({ title: '选择头像', icon: 'none' })
					}
				})
			},

			// 选择性别
			onSelectGender() {
				uni.showActionSheet({
					itemList: ['男', '女', '保密'],
					success: (res) => {
						const genders = ['男', '女', '保密']
						this.form.gender = genders[res.tapIndex]
					}
				})
			},

			// 生日picker变化
			onBirthdayChange(e) {
				this.form.birthday = e.detail.value
			},

			// 入职日期picker变化（员工）
			onJoinDateChange(e) {
				this.form.joinDate = e.detail.value
			},

			// 编辑字段（昵称 / 手机 / 邮箱 / 职位）
			onEditField(field) {
				const fieldMap = {
					nickname: { title: '编辑昵称', placeholder: '请输入昵称', value: this.form.nickname, max: 20 },
					phone: { title: '修改手机号', placeholder: '请输入手机号', value: this.form.phone.replace(/\*/g, ''), max: 11 },
					email: { title: '编辑邮箱', placeholder: '请输入邮箱地址', value: this.form.email, max: 50 },
					position: { title: '设置职位', placeholder: '请输入职位', value: this.form.position, max: 20 }
				}
				const cfg = fieldMap[field]
				if (!cfg) return

				uni.showModal({
					title: cfg.title,
					editable: true,
					placeholderText: cfg.placeholder,
					content: cfg.value || '',
					confirmText: '确认',
					confirmColor: '#2979ff',
					success: (r) => {
						if (r.confirm) {
							let val = (r.content || '').trim()
							if (field === 'phone' && val) {
								// 格式校验与脱敏回显
								if (!/^1\d{10}$/.test(val)) {
									uni.showToast({ title: '手机号格式不正确', icon: 'none' })
									return
								}
								val = val.slice(0, 3) + '****' + val.slice(7)
							}
							if (field === 'email' && val && !/^\S+@\S+\.\S+$/.test(val)) {
								uni.showToast({ title: '邮箱格式不正确', icon: 'none' })
								return
							}
							this.form[field] = val
							uni.showToast({ title: '已更新', icon: 'success' })
						}
					}
				})
			},

			// 保存
			onSave() {
				if (!this.form.nickname) {
					uni.showToast({ title: '请设置昵称', icon: 'none' })
					return
				}
				if (!this.form.gender) {
					uni.showToast({ title: '请选择性别', icon: 'none' })
					return
				}

				// 只写入表单字段，保留 storage 中原有的 enterprises 等数据，避免覆盖企业管理页改动
				const key = STORAGE_KEY + '_' + this.userRole
				const cur = uni.getStorageSync(key) || {}
				const payload = Object.assign({}, cur, this.form)
				uni.setStorageSync(key, payload)

				// 同步mine页面读取时需要的字段
				uni.setStorageSync('qcc_user_name_' + this.userRole, this.form.name)
				uni.setStorageSync('qcc_user_phone_' + this.userRole, this.form.phone)
				uni.setStorageSync('qcc_user_avatar_' + this.userRole, this.form.avatar)

				uni.showToast({
					title: '保存成功',
					icon: 'success',
					duration: 800,
					success: () => {
						setTimeout(() => uni.navigateBack(), 800)
					}
				})
			}
		}
	}
</script>

